#include <stdio.h>
#include <unistd.h>
#include <string.h>

int main() {
    int fd[2];
    pipe(fd);
    pid_t pid = fork();
    if (pid == 0) {
        // Child reads
        close(fd[1]);
        char buf[100];
        read(fd[0], buf, sizeof(buf));
        printf("Child read: %s
", buf);
    } else {
        // Parent writes
        close(fd[0]);
        const char *msg = "Hello through pipe";
        write(fd[1], msg, strlen(msg)+1);
    }
    return 0;
}

